INSERT INTO `block_content_revision__body` VALUES ('basic',0,1,1,'es',0,'<p>Leading company in comprehensive solutions for the hotel and industrial sectors in the Caribbean. Specialists in technical maintenance and construction.</p>','','basic_html'),('bloque_nosotros',0,2,2,'en',0,'<p><span class=\"HwtZe jCAhz ChMk0b ryNqvb\" jsname=\"W297wb\" jsaction=\"click:PDNqTc,GFf3ac,qlVvte;contextmenu:Nqw7Te,QP7LD; mouseout:Nqw7Te; mouseover:PDNqTc,c2aHje\" lang=\"en\" jscontroller=\"BiTO4b\"><strong>JOENRO CONSTRUCTION AND MAINTENANCE GROUP, S.R.L.</strong></span><span class=\"HwtZe\" jsname=\"jqKxS\" jsaction=\"mouseup:Sxi9L,BR6jm; mousedown:qjlr0e\" lang=\"en\"> </span><span class=\"HwtZe jCAhz ChMk0b ryNqvb\" jsname=\"W297wb\" jsaction=\"click:PDNqTc,GFf3ac,qlVvte;contextmenu:Nqw7Te,QP7LD; mouseout:Nqw7Te; mouseover:PDNqTc,c2aHje\" lang=\"en\" jscontroller=\"BiTO4b\">is a successfully established company in the hotel sector, offering a cost-effective and reliable solution.&nbsp;</span></p><p><span class=\"HwtZe jCAhz ChMk0b ryNqvb\" jsname=\"W297wb\" jsaction=\"click:PDNqTc,GFf3ac,qlVvte;contextmenu:Nqw7Te,QP7LD; mouseout:Nqw7Te; mouseover:PDNqTc,c2aHje\" lang=\"en\" jscontroller=\"BiTO4b\">Led by the <strong>Grupo Rodriguez</strong> team, we develop comprehensive solutions to meet specific needs within competitive budgets.</span></p>','','full_html'),('bloque_nosotros',0,2,2,'es',0,'<p><strong>JOENRO CONSTRUCTION AND MAINTENANCE GROUP, S.R.L.</strong> es una empresa establecida con éxito en el sector hotelero como una opción rentable y confiable.</p><p>Liderados por el equipo de <strong>Grupo Rodriguez</strong>, desarrollamos soluciones integrales para satisfacer necesidades específicas bajo presupuestos competitivos.</p>','','full_html'),('basic',0,4,4,'en',0,'<p>© 2026 JOENRO Construction and maintenance group, S.R.L. All rights reserved.</p>','','basic_html'),('basic',0,4,4,'es',0,'<p>© 2026 JOENRO Construction and maintenance group, S.R.L. Todos los derechos reservados.</p>','','basic_html'),('bloque_brochure',0,6,6,'en',0,'<p>Our detailed technical expertise in a single document. Discover why the leading hotel chains in the Caribbean choose us as their trusted partner.</p>','','full_html'),('bloque_brochure',0,6,6,'es',0,'<p>Nuestra experiencia técnica detallada en un solo documento. Descubra por qué las cadenas hoteleras más importantes del Caribe nos eligen como su socio de confianza.</p>','','full_html'),('basic',0,7,7,'en',0,'<p>JOENRO GROUP is not just a service company; it\'s a standard of quality. We apply advanced engineering methodologies to ensure that every project exceeds international standards.</p>','','basic_html'),('basic',0,7,7,'es',0,'<p>JOENRO GROUP no es solo una empresa de servicios; es un estándar de calidad. Aplicamos metodologías de ingeniería avanzada para asegurar que cada proyecto supere las normativas internacionales.</p>','','basic_html'),('bloque_icono',0,9,9,'en',0,'<p>Implementation of state-of-the-art equipment in air conditioning and mechanics.</p>','','full_html'),('bloque_icono',0,9,9,'es',0,'<p>Implementación de equipos de última generación en climatización y mecánica.</p>','','full_html'),('bloque_icono',0,10,10,'en',0,'<p>Strict industrial safety protocols at all our construction sites.</p>','','full_html'),('bloque_icono',0,10,10,'es',0,'<p>Protocolos estrictos de seguridad industrial en todas nuestras obras.</p>','','full_html'),('bloque_icono',0,11,11,'en',0,'<p>Immediate 24/7 response for hotel and industrial emergencies.</p>','','full_html'),('bloque_icono',0,11,11,'es',0,'<p>Respuesta inmediata 24/7 para emergencias hoteleras e industriales.</p>','','full_html'),('bloque_icono',0,12,12,'en',0,'<p>Energy optimization to reduce the client\'s environmental impact.</p>','','full_html'),('bloque_icono',0,12,12,'es',0,'<p>Optimización energética para reducir el impacto ambiental del cliente.</p>','','full_html'),('bloque_icono',0,14,14,'en',0,'<p>To ensure the continuous operation of our clients through state-of-the-art engineering and high-quality technical services.</p>','','full_html'),('bloque_icono',0,14,14,'es',0,'<p>Garantizar la operatividad continua de nuestros clientes mediante ingeniería de vanguardia y servicios técnicos de alta calidad.</p>','','full_html'),('bloque_icono',0,15,15,'en',0,'<p>To be the main strategic partner in comprehensive infrastructure solutions for the hotel sector throughout the Caribbean region.</p>','','full_html'),('bloque_icono',0,15,15,'es',0,'<p>Ser el aliado estratégico principal en soluciones integrales de infraestructura para el sector hotelero en toda la región del Caribe.</p>','','full_html'),('basic',0,16,16,'en',0,'<h2>Engineering with <em>Purpose</em></h2><p>JOENRO GROUP is the result of years of specialization in industrial maintenance and construction within the Caribbean tourism sector. We distinguish ourselves through our immediate response and technical precision in critical environments.</p>','','basic_html'),('basic',0,16,16,'es',0,'<h2>Ingeniería con <em>Propósito</em></h2><p>JOENRO GROUP es el resultado de años de especialización en el mantenimiento y construcción industrial dentro del sector turístico del Caribe. Nos distinguimos por nuestra capacidad de respuesta inmediata y la precisión técnica en entornos críticos.</p>','','basic_html'),('bloque_icono',0,24,24,'en',0,'<p>Detailed on-site technical evaluation by our engineers.</p>','','full_html'),('bloque_icono',0,24,24,'es',0,'<p>Evaluación técnica detallada en sitio por nuestros ingenieros.</p>','','full_html'),('bloque_icono',0,25,25,'en',0,'<p>Technical and economic proposal optimized to the budget.</p>','','full_html'),('bloque_icono',0,25,25,'es',0,'<p>Propuesta técnica y económica optimizada al presupuesto.</p>','','full_html'),('bloque_icono',0,26,26,'en',0,'<p>Implementation under strict safety and quality standards.</p>','','full_html'),('bloque_icono',0,26,26,'es',0,'<p>Implementación bajo estrictos estándares de seguridad y calidad.</p>','','full_html'),('bloque_icono',0,27,27,'en',0,'<p>Project delivery with guaranteed post-service support.</p>','','full_html'),('bloque_icono',0,27,27,'es',0,'<p>Entrega de proyecto con soporte post-servicio garantizado.</p>','','full_html'),('bloque_de_carta',0,28,28,'en',0,'We specialize in the thermal management of large hotel complexes. We understand that guest comfort is the number one priority, so we offer high-efficiency systems that guarantee optimal temperatures.','','restricted_html'),('bloque_de_carta',0,28,28,'es',0,'Somos especialistas en la gestión térmica de grandes complejos hoteleros. Entendemos que el confort del huésped es la prioridad número uno, por lo que ofrecemos sistemas de alta eficiencia que garantizan temperaturas óptimas.','','restricted_html'),('bloque_de_carta',0,29,29,'en',0,'We don\'t wait for things to fail. We implement programs that ensure your operations never stop. From industrial kitchens to engine rooms, Joenro Group is your technical support.','','restricted_html'),('bloque_de_carta',0,29,29,'es',0,'No esperamos a que las cosas fallen. Implementamos programas que aseguran que su operación nunca se detenga. Desde cocinas industriales hasta salas de máquinas, Joenro Group es su soporte técnico.','','restricted_html'),('bloque_de_enlace',0,30,30,'en',0,'<p>Our team is ready to evaluate your facilities in the Dominican Republic or Jamaica.</p>','','full_html'),('bloque_de_enlace',0,30,30,'es',0,'<p>Nuestro equipo está listo para evaluar sus instalaciones en República Dominicana o Jamaica.</p>','','full_html'),('bloque_de_enlace',0,32,32,'en',0,'<p>Our technical team is ready to advise you on your next project or maintenance plan.</p>','','full_html'),('bloque_de_enlace',0,32,32,'es',0,'<p>Nuestro equipo técnico está listo para asesorarle en su próxima obra o plan de mantenimiento.</p>','','full_html'),('basic',0,36,36,'es',0,'<p><button class=\"btn btn-primary\" type=\"button\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#offcanvasRight\" aria-controls=\"offcanvasRight\"><i class=\"fas fa-bars\"></i></button></p>','','full_html');
/*!40000 ALTER TABLE `block_content_revision__body` ENABLE KEYS */;
UNLOCK TABLES;

