INSERT INTO `block_content_revision__field_eslogan` VALUES ('bloque_de_encabezado',0,17,17,'en',0,'We build trust, we maintain your peace of mind','full_html'),('bloque_de_encabezado',0,17,17,'es',0,'Construimos confianza, mantenemos tu tranquilidad','full_html'),('bloque_de_encabezado',0,18,18,'en',0,'Specialized technical engineering and maintenance of critical infrastructure in the Caribbean.','full_html'),('bloque_de_encabezado',0,18,18,'es',0,'Ingeniería técnica especializada y mantenimiento de infraestructura crítica en el Caribe.','full_html'),('bloque_de_encabezado',0,31,31,'en',0,'Portfolio of solutions implemented in critical infrastructure.','full_html'),('bloque_de_encabezado',0,31,31,'es',0,'Portafolio de soluciones ejecutadas en infraestructura crítica.','full_html'),('bloque_de_encabezado',0,33,33,'en',0,'Innovation and industry news in the Caribbean.','full_html'),('bloque_de_encabezado',0,33,33,'es',0,'Innovación y noticias del sector en el Caribe.','full_html'),('bloque_de_encabezado',0,34,34,'en',0,'High-level structural maintenance in the Caribbean.','full_html'),('bloque_de_encabezado',0,34,34,'es',0,'Mantenimiento constructivo de alto nivel en el Caribe.','full_html');
