hed entirely.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:15:\"metatag-expires\";}s:15:\"original_source\";a:3:{s:4:\"name\";s:25:\"Avanzado: Fuente original\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:200:\"Used to indicate the URL that broke the story, and can link to either an internal URL or an external source. If the full URL is not known it is acceptable to use a partial URL or just the domain name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:23:\"metatag-original_source\";}s:9:\"generator\";a:3:{s:4:\"name\";s:19:\"Avanzado: Generador\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:97:\"Describes the name and version number of the software or publishing tool used to create the page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-generator\";}s:6:\"google\";a:3:{s:4:\"name\";s:16:\"Avanzado: Google\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:411:\"This meta tag communicates with Google. There are currently two directives supported: \'nositelinkssearchbox\' to not to show the sitelinks search box, and \'notranslate\' to ask Google not to offer a translation of the page. Both options may be added, just separate them with a comma. See <a href=\'https://support.google.com/webmasters/answer/79812?hl=en\'>meta tags that Google understands</a> for further details.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-google\";}s:4:\"icbm\";a:3:{s:4:\"name\";s:14:\"Avanzado: ICBM\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:227:\"Geo-spatial information in \'latitude, longitude\' format, e.g. \'50.167958, -97.133185\'; <a href=\'https://en.wikipedia.org/wiki/ICBM_address\' aria-label=\'see Wikipedia for details on ICBM addresses\'>see Wikipedia for details</a>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:12:\"metatag-icbm\";}s:9:\"image_src\";a:3:{s:4:\"name\";s:15:\"Avanzado: Image\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:97:\"An image associated with this page, for use as a thumbnail in social networks and other services.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-image_src\";}s:4:\"next\";a:3:{s:4:\"name\";s:23:\"Avanzado: Next page URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:65:\"Used for paginated content by providing URL with rel=\'next\' link.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:12:\"metatag-next\";}s:13:\"geo_placename\";a:3:{s:4:\"name\";s:38:\"Avanzado: Nombre del lugar geográfico\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:25:\"A location\'s formal name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-geo_placename\";}s:8:\"referrer\";a:3:{s:4:\"name\";s:33:\"Avanzado: Política de remitentes\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:280:\"Indicate to search engines and other page scrapers whether or not links should be followed. See <a href=\'https://w3c.github.io/webappsec/specs/referrer-policy/\'>the W3C specifications</a> for further details. Note: this serves the same purpose as the HTTP header by the same name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-referrer\";}s:12:\"geo_position\";a:3:{s:4:\"name\";s:31:\"Avanzado: Posición geográfica\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:261:\"Geo-spatial information in \'latitude; longitude\' format, e.g. \'50.167958; -97.133185\'; <a href=\'https://en.wikipedia.org/wiki/Geographic_coordinate_system\' aria-label=\'see Wikipedia for details on the geographic coordinate system\'>see Wikipedia for details</a>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:20:\"metatag-geo_position\";}s:6:\"pragma\";a:3:{s:4:\"name\";s:16:\"Avanzado: Pragma\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:147:\"Used to control whether a browser caches a specific page locally. Not commonly used. Should be used in conjunction with the Cache-Control meta tag.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-pragma\";}s:4:\"prev\";a:3:{s:4:\"name\";s:27:\"Avanzado: Previous page URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:65:\"Used for paginated content by providing URL with rel=\'prev\' link.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:12:\"metatag-prev\";}s:10:\"geo_region\";a:3:{s:4:\"name\";s:29:\"Avanzado: Región geográfica\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:130:\"A location\'s two-letter international country code, with an optional two-letter region, e.g. \'US-NH\' for New Hampshire in the USA.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:18:\"metatag-geo_region\";}s:13:\"revisit_after\";a:3:{s:4:\"name\";s:23:\"Avanzado: Revisit After\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:193:\"Tell search engines when to index the page again. Very few search engines support this tag, it is more useful to use an <a href=\'https://www.drupal.org/project/xmlsitemap\'>XML Sitemap</a> file.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-revisit_after\";}s:6:\"robots\";a:3:{s:4:\"name\";s:16:\"Avanzado: Robots\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:90:\"Provides search engines with specific directions for what to do when this page is indexed.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-robots\";}s:10:\"set_cookie\";a:3:{s:4:\"name\";s:20:\"Avanzado: Set cookie\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:251:\"<a href=\'https://www.metatags.org/meta_http_equiv_set_cookie\'>Sets a cookie</a> on the visitor\'s browser. Can be in either NAME=VALUE format, or a more verbose format including the path and expiration date; see the link for full details on the syntax.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:18:\"metatag-set_cookie\";}s:13:\"canonical_url\";a:3:{s:4:\"name\";s:23:\"Avanzado: URL canónica\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:140:\"A link to the preferred page location or URL of the content of this page, to help eliminate duplicate content penalties from search engines.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-canonical_url\";}s:9:\"shortlink\";a:3:{s:4:\"name\";s:19:\"Avanzado: URL corta\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:55:\"A brief URL, often created by a URL shortening service.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-shortlink\";}s:6:\"rating\";a:3:{s:4:\"name\";s:19:\"Avanzado: Votación\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:454:\"Used to rate content for audience appropriateness. This tag has little known influence on search engine rankings, but can be used by browsers, browser extensions, and apps. The <a href=\'https://www.metatags.org/meta_name_rating\'>most common options</a> are general, mature, restricted, 14 years, safe for kids. If you follow the <a href=\'https://www.rtalabel.org/index.php?content=howto\'>RTA Documentation</a> you should enter RTA-5042-1996-1400-1577-RTA\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-rating\";}s:16:\"video_actor_role\";a:3:{s:4:\"name\";s:29:\"Open Graph: Actor&#039;s role\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:26:\"The roles of the actor(s).\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:30:\"list<metatag-video_actor_role>\";}s:11:\"video_actor\";a:3:{s:4:\"name\";s:21:\"Open Graph: Actor(es)\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:69:\"Links to the Facebook profiles for actor(s) that appear in the video.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"list<metatag-video_actor>\";}s:15:\"og_video_height\";a:3:{s:4:\"name\";s:25:\"Open Graph: Alto de video\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:129:\"The height of the above video(s). Note: if both the unsecured and secured videos are provided, they should both be the same size.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:23:\"metatag-og_video_height\";}s:15:\"og_image_height\";a:3:{s:4:\"name\";s:31:\"Open Graph: Altura de la imagen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:129:\"The height of the above image(s). Note: if both the unsecured and secured images are provided, they should both be the same size.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:23:\"metatag-og_image_height\";}s:14:\"og_video_width\";a:3:{s:4:\"name\";s:26:\"Open Graph: Ancho de video\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:129:\"The height of the above video(s). Note: if both the unsecured and secured videos are provided, they should both be the same size.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:22:\"metatag-og_video_width\";}s:14:\"og_image_width\";a:3:{s:4:\"name\";s:29:\"Open Graph: Anchura de imagen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:128:\"The width of the above image(s). Note: if both the unsecured and secured images are provided, they should both be the same size.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:22:\"metatag-og_image_width\";}s:17:\"profile_last_name\";a:3:{s:4:\"name\";s:21:\"Open Graph: Apellidos\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:23:\"The person\'s last name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"metatag-profile_last_name\";}s:19:\"og_audio_secure_url\";a:3:{s:4:\"name\";s:28:\"Open Graph: Audio secure URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:127:\"The secure URL to an audio file that complements this object. All \'http://\' URLs will automatically be converted to \'https://\'.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:27:\"metatag-og_audio_secure_url\";}s:13:\"og_audio_type\";a:3:{s:4:\"name\";s:22:\"Open Graph: Audio type\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:84:\"The MIME type of the audio file. Examples include \'application/mp3\' for an MP3 file.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-og_audio_type\";}s:8:\"og_audio\";a:3:{s:4:\"name\";s:21:\"Open Graph: Audio URL\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:54:\"The URL to an audio file that complements this object.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-og_audio\";}s:14:\"article_author\";a:3:{s:4:\"name\";s:31:\"Open Graph: Autor del artículo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:131:\"Links an article to an author\'s Facebook profile, should be either URLs to the author\'s profile page or their Facebook profile IDs.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:28:\"list<metatag-article_author>\";}s:11:\"book_author\";a:3:{s:4:\"name\";s:27:\"Open Graph: Autor del libro\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:127:\"Links a book to an author\'s Facebook profile, should be either URLs to the author\'s profile page or their Facebook profile IDs.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"list<metatag-book_author>\";}s:21:\"og_locale_alternative\";a:3:{s:4:\"name\";s:50:\"Open Graph: Configuraciones de idioma alternativas\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:99:\"Other locales this content is available in, must be in the format language_TERRITORY, e.g. \'fr_FR\'.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:35:\"list<metatag-og_locale_alternative>\";}s:17:\"fediverse_creator\";a:3:{s:4:\"name\";s:44:\"Open Graph: Creator&#039;s fediverse account\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:101:\"The fediverse @username for the content creator / author for this page, including the first @ symbol.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:31:\"list<metatag-fediverse_creator>\";}s:14:\"og_postal_code\";a:3:{s:4:\"name\";s:30:\"Open Graph: Código postal/ZIP\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:22:\"metatag-og_postal_code\";}s:14:\"og_description\";a:3:{s:4:\"name\";s:24:\"Open Graph: Descripción\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:49:\"A one to two sentence description of the content.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:22:\"metatag-og_description\";}s:13:\"og_determiner\";a:3:{s:4:\"name\";s:24:\"Open Graph: Determinador\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:166:\"The word that appears before the content\'s title in a sentence. The default ignores this value, the \'Automatic\' value should be sufficient if this is actually needed.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-og_determiner\";}s:17:\"og_street_address\";a:3:{s:4:\"name\";s:22:\"Open Graph: Dirección\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:25:\"metatag-og_street_address\";}s:8:\"og_email\";a:3:{s:4:\"name\";s:45:\"Open Graph: Dirección de correo electrónico\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:16:\"metatag-og_email\";}s:14:\"video_director\";a:3:{s:4:\"name\";s:23:\"Open Graph: Director(s)\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:72:\"Links to the Facebook profiles for director(s) that worked on the video.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:28:\"list<metatag-video_director>\";}s:17:\"article_publisher\";a:3:{s:4:\"name\";s:32:\"Open Graph: Editor del artículo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:48:\"Links an article to a publisher\'s Facebook page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"metatag-article_publisher\";}s:11:\"article_tag\";a:3:{s:4:\"name\";s:37:\"Open Graph: Etiqueta(s) del artículo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:38:\"Appropriate keywords for this content.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"list<metatag-article_tag>\";}s:8:\"book_tag\";a:3:{s:4:\"name\";s:32:\"Open Graph: Etiqueta(s) de libro\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:38:\"Appropriate keywords for this content.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:22:\"list<metatag-book_tag>\";}s:18:\"video_release_date\";a:3:{s:4:\"name\";s:32:\"Open Graph: Fecha de lanzamiento\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:32:\"The date the video was released.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:26:\"metatag-video_release_date\";}s:17:\"book_release_date\";a:3:{s:4:\"name\";s:33:\"Open Graph: Fecha de publicación\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:31:\"The date the book was released.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"metatag-book_release_date\";}s:23:\"article_expiration_time\";a:3:{s:4:\"name\";s:53:\"Open Graph: Fecha y hora de expiración del artículo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:148:\"The date this content will expire, with an optional time value. Needs to be in <a href=\'https://en.wikipedia.org/wiki/ISO_8601\'>ISO 8601</a> format.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:31:\"metatag-article_expiration_time\";}s:21:\"article_modified_time\";a:3:{s:4:\"name\";s:55:\"Open Graph: Fecha y hora de modificación del artículo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:154:\"The date this content was last modified, with an optional time value. Needs to be in <a href=\'https://en.wikipedia.org/wiki/ISO_8601\'>ISO 8601</a> format.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:29:\"metatag-article_modified_time\";}s:15:\"og_updated_time\";a:3:{s:4:\"name\";s:55:\"Open Graph: Fecha y hora de modificación del contenido\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:210:\"The date this content was last modified, with an optional time value. Needs to be in <a href=\'https://en.wikipedia.org/wiki/ISO_8601\'>ISO 8601</a> format. Can be the same as the \'Article modification date\' tag.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:23:\"metatag-og_updated_time\";}s:22:\"article_published_time\";a:3:{s:4:\"name\";s:54:\"Open Graph: Fecha y hora de publicación del artículo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:153:\"The date this content was published on, with an optional time value. Needs to be in <a href=\'https://en.wikipedia.org/wiki/ISO_8601\'>ISO 8601</a> format.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:30:\"metatag-article_published_time\";}s:14:\"profile_gender\";a:3:{s:4:\"name\";s:19:\"Open Graph: Género\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:93:\"Any of Facebook\'s gender values should be allowed, the initial two being \'male\' and \'female\'.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:22:\"metatag-profile_gender\";}s:8:\"og_image\";a:3:{s:4:\"name\";s:17:\"Open Graph: Image\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:435:\"The URL of an image which should represent the content. The image must be at least 200 x 200 pixels in size; 600 x 316 pixels is a recommended minimum size, and for best results use an image least 1200 x 630 pixels in size. Supports PNG, JPEG and GIF formats. Should not be used if og:image:url is used. Note: if multiple images are added many services (e.g. Facebook) will default to the largest image, not specifically the first one.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:22:\"list<metatag-og_image>\";}s:12:\"og_image_alt\";a:3:{s:4:\"name\";s:33:\"Open Graph: Image &#039;alt&#039;\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:119:\"A description of what is in the image, not a caption. If the page specifies an og:image it should specify og:image:alt.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:20:\"metatag-og_image_alt\";}s:9:\"book_isbn\";a:3:{s:4:\"name\";s:16:\"Open Graph: ISBN\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:15:\"The Book\'s ISBN\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-book_isbn\";}s:11:\"og_latitude\";a:3:{s:4:\"name\";s:19:\"Open Graph: Latitud\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:19:\"metatag-og_latitude\";}s:11:\"og_locality\";a:3:{s:4:\"name\";s:21:\"Open Graph: Localidad\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:19:\"metatag-og_locality\";}s:12:\"og_longitude\";a:3:{s:4:\"name\";s:20:\"Open Graph: Longitud\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:20:\"metatag-og_longitude\";}s:18:\"profile_first_name\";a:3:{s:4:\"name\";s:18:\"Open Graph: Nombre\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:56:\"The first name of the person who\'s Profile page this is.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:26:\"metatag-profile_first_name\";}s:15:\"og_country_name\";a:3:{s:4:\"name\";s:28:\"Open Graph: Nombre del país\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:23:\"metatag-og_country_name\";}s:12:\"og_site_name\";a:3:{s:4:\"name\";s:28:\"Open Graph: Nombre del sitio\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:56:\"A human-readable name for the site, e.g., <em>IMDb</em>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:20:\"metatag-og_site_name\";}s:16:\"profile_username\";a:3:{s:4:\"name\";s:29:\"Open Graph: Nombre de usuario\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:35:\"A pseudonym / alias of this person.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:24:\"metatag-profile_username\";}s:13:\"og_fax_number\";a:3:{s:4:\"name\";s:26:\"Open Graph: Número de fax\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:21:\"metatag-og_fax_number\";}s:15:\"og_phone_number\";a:3:{s:4:\"name\";s:32:\"Open Graph: Número de teléfono\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:23:\"metatag-og_phone_number\";}s:9:\"og_locale\";a:3:{s:4:\"name\";s:28:\"Open Graph: Regionalización\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:101:\"The locale these tags are marked up in, must be in the format language_TERRITORY. Default is \'en_US\'.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:17:\"metatag-og_locale\";}s:9:\"og_region\";a:3:{s:4:\"name\";s:19:\"Open Graph: Región\";s:11:\"description\";s:0:\"\";s:4:\"type\";s:17:\"metatag-og_region\";}s:12:\"video_writer\";a:3:{s:4:\"name\";s:27:\"Open Graph: Scriptwriter(s)\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:65:\"Links to the Facebook profiles for scriptwriter(s) for the video.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:26:\"list<metatag-video_writer>\";}s:15:\"article_section\";a:3:{s:4:\"name\";s:34:\"Open Graph: Sección del artículo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:59:\"The primary section of this website the content belongs to.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:23:\"metatag-article_section\";}s:12:\"video_series\";a:3:{s:4:\"name\";s:18:\"Open Graph: Series\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:35:\"The TV show this series belongs to.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:20:\"metatag-video_series\";}s:9:\"video_tag\";a:3:{s:4:\"name\";s:21:\"Open Graph: Tag words\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:37:\"Tag words associated with this video.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:23:\"list<metatag-video_tag>\";}s:7:\"og_type\";a:3:{s:4:\"name\";s:29:\"Open Graph: Tipo de contenido\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:46:\"The type of the content, e.g., <em>movie</em>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:15:\"metatag-og_type\";}s:13:\"og_image_type\";a:3:{s:4:\"name\";s:26:\"Open Graph: Tipo de imagen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:254:\"The type of image referenced above. Should be either \'image/gif\' for a GIF image, \'image/jpeg\' for a JPG/JPEG image, or \'image/png\' for a PNG image. Note: there should be one value for each image, and having more than there are images may cause problems.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-og_image_type\";}s:13:\"og_video_type\";a:3:{s:4:\"name\";s:27:\"Open Graph: Tipo del vídeo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:219:\"The type of video referenced above. Should be either  video.episode, video.movie, video.other, and video.tv_show. Note: there should be one value for each video, and having more than there are videos may cause problems.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:21:\"metatag-og_video_type\";}s:8:\"og_title\";a:3:{s:4:\"name\";s:19:\"Open Graph: Título\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:50:\"The title of the content, e.g., <em>The Rock</em>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-og_title\";}s:12:\"og_image_url\";a:3:{s:4:\"name\";s:25:\"Open Graph: URL de imagen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:99:\"A alternative version of og:image and has exactly the same requirements; only one needs to be used.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:26:\"list<metatag-og_image_url>\";}s:8:\"og_video\";a:3:{s:4:\"name\";s:26:\"Open Graph: URL del vídeo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:276:\"The URL of an video which should represent the content. For best results use a source that is at least 1200 x 630 pixels in size, but at least 600 x 316 pixels is a recommended minimum. Object types supported include video.episode, video.movie, video.other, and video.tv_show.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:22:\"list<metatag-og_video>\";}s:6:\"og_url\";a:3:{s:4:\"name\";s:26:\"Open Graph: URL de página\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:140:\"Preferred page location or URL to help eliminate duplicate content for search engines, e.g., <em>https://www.imdb.com/title/tt0117500/</em>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:14:\"metatag-og_url\";}s:19:\"og_image_secure_url\";a:3:{s:4:\"name\";s:35:\"Open Graph: URL segura de la imagen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:274:\"The secure URL (HTTPS) of an image which should represent the content. The image must be at least 200 x 200 pixels in size; 600 x 316 pixels is a recommended minimum size, and for best results use an image least 1200 x 630 pixels in size. Supports PNG, JPEG and GIF formats.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:33:\"list<metatag-og_image_secure_url>\";}s:19:\"og_video_secure_url\";a:3:{s:4:\"name\";s:33:\"Open Graph: URL segura del vídeo\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:70:\"The secure URL (HTTPS) of an video which should represent the content.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:27:\"metatag-og_video_secure_url\";}s:11:\"og_see_also\";a:3:{s:4:\"name\";s:24:\"Open Graph: Ver también\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:23:\"URLs to related content\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"list<metatag-og_see_also>\";}s:17:\"og_video_duration\";a:3:{s:4:\"name\";s:36:\"Open Graph: Video duration (seconds)\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:34:\"The length of the video in seconds\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:25:\"metatag-og_video_duration\";}s:11:\"description\";a:3:{s:4:\"name\";s:27:\"Tags básicos: Descripción\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:206:\"A brief and concise summary of the page\'s content that is a maximum of 160 characters in length. The description meta tag may be used by search engines to display a snippet about the page in search results.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:19:\"metatag-description\";}s:8:\"keywords\";a:3:{s:4:\"name\";s:29:\"Tags básicos: Palabras clave\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:120:\"A comma-separated list of keywords about the page. This meta tag is <em>no longer</em> supported by most search engines.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-keywords\";}s:8:\"abstract\";a:3:{s:4:\"name\";s:22:\"Tags básicos: Resumen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:341:\"A brief and concise summary of the page\'s content, preferably 150 characters or less. Where as the description meta tag may be used by search engines to display a snippet about the page in search results, the abstract tag may be used to archive a summary about the page. This meta tag is <em>no longer</em> supported by major search engines.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:16:\"metatag-abstract\";}s:5:\"title\";a:3:{s:4:\"name\";s:36:\"Tags básicos: Título de la página\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:437:\"The text to display in the title bar of a visitor\'s web browser when they view this page. This meta tag may also be used as the title of the page when a visitor bookmarks or favorites this page, or as the page title in a search engine result. It is common to append \'[site:name]\' to the end of this, so the site\'s name is automatically added. It is recommended that the title is no greater than 55 - 65 characters long, including spaces.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:13:\"metatag-title\";}s:27:\"twitter_cards_player_height\";a:3:{s:4:\"name\";s:47:\"Twitter Cards: Altura del reproductor de medios\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:91:\"The height of the media player iframe, in pixels. Required when using the Player Card type.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:35:\"metatag-twitter_cards_player_height\";}s:26:\"twitter_cards_player_width\";a:3:{s:4:\"name\";s:48:\"Twitter Cards: Anchura del reproductor de medios\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:90:\"The width of the media player iframe, in pixels. Required when using the Player Card type.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:34:\"metatag-twitter_cards_player_width\";}s:24:\"twitter_cards_creator_id\";a:3:{s:4:\"name\";s:48:\"Twitter Cards: Creator&#039;s Twitter account ID\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:80:\"The numerical Twitter account ID for the content creator / author for this page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:32:\"metatag-twitter_cards_creator_id\";}s:21:\"twitter_cards_creator\";a:3:{s:4:\"name\";s:42:\"Twitter Cards: Cuenta de Twitter del autor\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:85:\"The @username for the content creator / author for this page, including the @ symbol.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:29:\"metatag-twitter_cards_creator\";}s:18:\"twitter_cards_site\";a:3:{s:4:\"name\";s:46:\"Twitter Cards: Cuenta de Twitter del sitio web\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:103:\"The @username for the website, which will be displayed in the Card\'s footer; must include the @ symbol.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:26:\"metatag-twitter_cards_site\";}s:25:\"twitter_cards_description\";a:3:{s:4:\"name\";s:27:\"Twitter Cards: Descripción\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:310:\"A description that concisely summarizes the content of the page, as appropriate for presentation within a Tweet. Do not re-use the title text as the description, or use this field to describe the general services provided by the website. The string will be truncated, by Twitter, at the word to 200 characters.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:33:\"metatag-twitter_cards_description\";}s:32:\"twitter_cards_app_url_googleplay\";a:3:{s:4:\"name\";s:76:\"Twitter Cards: Esquema de URL personalizado de la aplicación de Google Play\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:83:\"The Google Play app\'s custom URL scheme (must include \"://\" after the scheme name).\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:40:\"metatag-twitter_cards_app_url_googleplay\";}s:26:\"twitter_cards_app_url_ipad\";a:3:{s:4:\"name\";s:69:\"Twitter Cards: Esquema de URL personalizado de la aplicación de iPad\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:76:\"The iPad app\'s custom URL scheme (must include \"://\" after the scheme name).\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:34:\"metatag-twitter_cards_app_url_ipad\";}s:28:\"twitter_cards_app_url_iphone\";a:3:{s:4:\"name\";s:71:\"Twitter Cards: Esquema de URL personalizado de la aplicación de iPhone\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:78:\"The iPhone app\'s custom URL scheme (must include \"://\" after the scheme name).\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:36:\"metatag-twitter_cards_app_url_iphone\";}s:31:\"twitter_cards_app_id_googleplay\";a:3:{s:4:\"name\";s:58:\"Twitter Cards: Identificador de aplicación de Google Play\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:62:\"Your app ID in the Google Play Store (i.e. \"com.android.app\").\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:39:\"metatag-twitter_cards_app_id_googleplay\";}s:25:\"twitter_cards_app_id_ipad\";a:3:{s:4:\"name\";s:51:\"Twitter Cards: Identificador de aplicación de iPad\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:90:\"String value, should be the numeric representation of your iPad app\'s ID in the App Store.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:33:\"metatag-twitter_cards_app_id_ipad\";}s:27:\"twitter_cards_app_id_iphone\";a:3:{s:4:\"name\";s:53:\"Twitter Cards: Identificador de aplicación de iPhone\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:92:\"String value, should be the numeric representation of your iPhone app\'s ID in the App Store.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:35:\"metatag-twitter_cards_app_id_iphone\";}s:21:\"twitter_cards_site_id\";a:3:{s:4:\"name\";s:63:\"Twitter Cards: Identificador de cuenta de Twitter del sitio web\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:95:\"The numerical Twitter account ID for the website, which will be displayed in the Card\'s footer.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:29:\"metatag-twitter_cards_site_id\";}s:33:\"twitter_cards_app_name_googleplay\";a:3:{s:4:\"name\";s:54:\"Twitter Cards: Nombre de la aplicación de Google Play\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:49:\"The name of the app in the Google Play app store.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:41:\"metatag-twitter_cards_app_name_googleplay\";}s:27:\"twitter_cards_app_name_ipad\";a:3:{s:4:\"name\";s:47:\"Twitter Cards: Nombre de la aplicación de iPad\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:25:\"The name of the iPad app.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:35:\"metatag-twitter_cards_app_name_ipad\";}s:29:\"twitter_cards_app_name_iphone\";a:3:{s:4:\"name\";s:49:\"Twitter Cards: Nombre de la aplicación de iPhone\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:27:\"The name of the iPhone app.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:37:\"metatag-twitter_cards_app_name_iphone\";}s:31:\"twitter_cards_app_store_country\";a:3:{s:4:\"name\";s:36:\"Twitter Cards: País de la App store\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:162:\"If your application is not available in the US App Store, you must set this value to the two-letter country code for the App Store that contains your application.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:39:\"metatag-twitter_cards_app_store_country\";}s:23:\"twitter_cards_image_alt\";a:3:{s:4:\"name\";s:45:\"Twitter Cards: Texto alternativo de la imagen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:77:\"The alternative text of the image being linked to. Limited to 420 characters.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:31:\"metatag-twitter_cards_image_alt\";}s:18:\"twitter_cards_type\";a:3:{s:4:\"name\";s:41:\"Twitter Cards: Tipo de tarjeta de Twitter\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:426:\"Notes:<ul><li>no other fields are required for a Summary card</li><li>Media player card requires the \'title\', \'description\', \'media player URL\', \'media player width\', \'media player height\' and \'image\' fields,</li><li>Summary Card with Large Image card requires the \'Summary\' field and the \'image\' field,</li><li>App Card requires the \'iPhone app ID\' field, the \'iPad app ID\' field and the \'Google Play app ID\' field,</li></ul>\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:26:\"metatag-twitter_cards_type\";}s:40:\"twitter_cards_player_stream_content_type\";a:3:{s:4:\"name\";s:58:\"Twitter Cards: Tipo MIME de la transmisión multimedia MP4\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:99:\"The MIME type for the media contained in the stream URL, as defined by <a href=\':url\'>RFC 4337</a>.\";s:12:\"\0*\0arguments\";a:1:{s:4:\":url\";s:38:\"https://tools.ietf.org/rfc/rfc4337.txt\";}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:48:\"metatag-twitter_cards_player_stream_content_type\";}s:19:\"twitter_cards_title\";a:3:{s:4:\"name\";s:22:\"Twitter Cards: Título\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:163:\"The page\'s title, which should be concise; it will be truncated at 70 characters by Twitter. This field is required unless this the \'type\' field is set to \'photo\'.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:27:\"metatag-twitter_cards_title\";}s:19:\"twitter_cards_image\";a:3:{s:4:\"name\";s:28:\"Twitter Cards: URL de imagen\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:385:\"The URL to a unique image representing the content of the page. Do not use a generic image such as your website logo, author photo, or other image that spans multiple pages. Images larger than 120x120px will be resized and cropped square based on longest dimension. Images smaller than 60x60px will not be shown. If the \'type\' is set to Photo then the image must be at least 280x150px.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:27:\"metatag-twitter_cards_image\";}s:27:\"twitter_cards_player_stream\";a:3:{s:4:\"name\";s:52:\"Twitter Cards: URL de la transmisión multimedia MP4\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:112:\"The full URL for an MP4 video (h.264) or audio (AAC) stream, takes precedence over the other media player field.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:35:\"metatag-twitter_cards_player_stream\";}s:20:\"twitter_cards_player\";a:3:{s:4:\"name\";s:44:\"Twitter Cards: URL del reproductor de medios\";s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:181:\"The full URL for loading a media player, specifically an iframe for an embedded video rather than the URL to a page that contains a player. Required when using the Player Card type.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"type\";s:28:\"metatag-twitter_cards_player\";}}s:14:\"metatag-rating\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:19:\"Avanzado: Votación\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:3388;}}s:14:\"metatag-rights\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:18:\"Avanzado: Derechos\";s:6:\"module\";s:7:\"metatag\";s:11:\"description\";r:3255;}}s:21:\"metatag-cache_control\";a:1:{s:5:\"value\";a:3:{s:4:\"name\";s:23:\"Avanzado: Cache control\";s:6:\"mod