:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:130:\"A location\'s two-letter international country code, with an optional two-letter region, e.g. \'US-NH\' for New Hampshire in the USA.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:10:\"geo.region\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:0;s:4:\"type\";s:5:\"label\";s:6:\"secure\";i:0;s:8:\"multiple\";b:0;s:5:\"class\";s:43:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\GeoRegion\";s:8:\"provider\";s:7:\"metatag\";}s:7:\"refresh\";a:11:{s:2:\"id\";s:7:\"refresh\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:7:\"Refresh\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:190:\"The number of seconds to wait before refreshing the page. May also force redirect to another page using the format \'5; url=https://example.com/\', which would be triggered after five seconds.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:7:\"refresh\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:5;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:41:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Refresh\";s:8:\"provider\";s:7:\"metatag\";}s:11:\"description\";a:13:{s:2:\"id\";s:11:\"description\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:11:\"Description\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:206:\"A brief and concise summary of the page\'s content that is a maximum of 160 characters in length. The description meta tag may be used by search engines to display a snippet about the page in search results.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:11:\"description\";s:5:\"group\";s:5:\"basic\";s:6:\"weight\";i:2;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:4:\"long\";b:1;s:9:\"trimmable\";b:1;s:5:\"class\";s:45:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Description\";s:8:\"provider\";s:7:\"metatag\";}s:8:\"abstract\";a:13:{s:2:\"id\";s:8:\"abstract\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:8:\"Abstract\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:341:\"A brief and concise summary of the page\'s content, preferably 150 characters or less. Where as the description meta tag may be used by search engines to display a snippet about the page in search results, the abstract tag may be used to archive a summary about the page. This meta tag is <em>no longer</em> supported by major search engines.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:8:\"abstract\";s:5:\"group\";s:5:\"basic\";s:6:\"weight\";i:3;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:9:\"trimmable\";b:1;s:4:\"long\";b:1;s:5:\"class\";s:45:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\AbstractTag\";s:8:\"provider\";s:7:\"metatag\";}s:10:\"set_cookie\";a:11:{s:2:\"id\";s:10:\"set_cookie\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:10:\"Set cookie\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:251:\"<a href=\'https://www.metatags.org/meta_http_equiv_set_cookie\'>Sets a cookie</a> on the visitor\'s browser. Can be in either NAME=VALUE format, or a more verbose format including the path and expiration date; see the link for full details on the syntax.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:10:\"set-cookie\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:5;s:4:\"type\";s:6:\"string\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:43:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\SetCookie\";s:8:\"provider\";s:7:\"metatag\";}s:12:\"geo_position\";a:11:{s:2:\"id\";s:12:\"geo_position\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:21:\"Geographical position\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:261:\"Geo-spatial information in \'latitude; longitude\' format, e.g. \'50.167958; -97.133185\'; <a href=\'https://en.wikipedia.org/wiki/Geographic_coordinate_system\' aria-label=\'see Wikipedia for details on the geographic coordinate system\'>see Wikipedia for details</a>.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:12:\"geo.position\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:0;s:4:\"type\";s:5:\"label\";s:6:\"secure\";i:0;s:8:\"multiple\";b:0;s:5:\"class\";s:45:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\GeoPosition\";s:8:\"provider\";s:7:\"metatag\";}s:8:\"referrer\";a:11:{s:2:\"id\";s:8:\"referrer\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:15:\"Referrer policy\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:280:\"Indicate to search engines and other page scrapers whether or not links should be followed. See <a href=\'https://w3c.github.io/webappsec/specs/referrer-policy/\'>the W3C specifications</a> for further details. Note: this serves the same purpose as the HTTP header by the same name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:8:\"referrer\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:5;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:42:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Referrer\";s:8:\"provider\";s:7:\"metatag\";}s:13:\"revisit_after\";a:11:{s:2:\"id\";s:13:\"revisit_after\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:13:\"Revisit After\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:193:\"Tell search engines when to index the page again. Very few search engines support this tag, it is more useful to use an <a href=\'https://www.drupal.org/project/xmlsitemap\'>XML Sitemap</a> file.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:13:\"revisit-after\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:8;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:46:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\RevisitAfter\";s:8:\"provider\";s:7:\"metatag\";}s:15:\"original_source\";a:11:{s:2:\"id\";s:15:\"original_source\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:15:\"Original source\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:200:\"Used to indicate the URL that broke the story, and can link to either an internal URL or an external source. If the full URL is not known it is acceptable to use a partial URL or just the domain name.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:15:\"original-source\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:4;s:4:\"type\";s:3:\"uri\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:48:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\OriginalSource\";s:8:\"provider\";s:7:\"metatag\";}s:6:\"author\";a:11:{s:2:\"id\";s:6:\"author\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:6:\"Author\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:28:\"Define the author of a page.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:6:\"author\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:4;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:40:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Author\";s:8:\"provider\";s:7:\"metatag\";}s:6:\"google\";a:11:{s:2:\"id\";s:6:\"google\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:6:\"Google\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:411:\"This meta tag communicates with Google. There are currently two directives supported: \'nositelinkssearchbox\' to not to show the sitelinks search box, and \'notranslate\' to ask Google not to offer a translation of the page. Both options may be added, just separate them with a comma. See <a href=\'https://support.google.com/webmasters/answer/79812?hl=en\'>meta tags that Google understands</a> for further details.\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:4:\"name\";s:6:\"google\";s:5:\"group\";s:8:\"advanced\";s:6:\"weight\";i:5;s:4:\"type\";s:5:\"label\";s:6:\"secure\";b:0;s:8:\"multiple\";b:0;s:5:\"class\";s:40:\"Drupal\\metatag\\Plugin\\metatag\\Tag\\Google\";s:8:\"provider\";s:7:\"metatag\";}s:9:\"generator\";a:11:{s:2:\"id\";s:9:\"generator\";s:5:\"label\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:9:\"Generator\";s:12:\"\0*\0arguments\";a:0:{}s:10:\"\0*\0options\";a:0:{}}s:11:\"description\";O:48:\"Drupal\\Core\\StringTranslation\\TranslatableMarkup\":3:{s:9:\"\0*\0string\";s:97: