58266ae2f6e4aa230fbbb87bd699c0e3:[theme]=gin:[user.permissions]=is-admin',_binary 'a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:641:\"<div id=\"block-gin-help\" role=\"complementary\" class=\"block block-help block-help-block\">\n  \n    \n      <p>Bulk generation can be used to generate URL aliases for items that currently have no aliases. This is typically used when installing Pathauto on a site that has existing un-aliased content that needs to be aliased in bulk.<br>It can also be used to regenerate URL aliases for items that have an old alias and for which the Pathauto pattern has been changed.</p><p>Note that this will only affect items which are configured to have their URL alias automatically set. Items whose URL alias is manually set are not affected.</p>\n  </div>\n\";}s:9:\"#attached\";a:0:{}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"route\";i:2;s:5:\"theme\";i:3;s:16:\"user.permissions\";}s:4:\"tags\";a:2:{i:0;s:10:\"block_view\";i:1;s:27:\"config:block.block.gin_help\";}s:7:\"max-age\";i:-1;}}',-1,1777748538.500,1,'block_view config:block.block.gin_help rendered','0'),('entity_view:block:gin_help:[languages:language_interface]=es:[route]=simple_sitemap.custom35786c7117b4e38d0f169239752ce71158266ae2f6e4aa230fbbb87bd699c0e3:[theme]=gin:[user.permissions]=is-admin',_binary 'a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:756:\"<div id=\"block-gin-help\" role=\"complementary\" class=\"block block-help block-help-block\">\n  \n    \n      <p>Add custom internal drupal paths to specific sitemaps.</p><p>Specify drupal internal (relative) paths, one per line. Do not forget to prepend the paths with a \'/\'.<br>Optionally link priority <em>(0.0 - 1.0)</em> can be added by appending it after a space.<br> Optionally link change frequency <em>(always / hourly / daily / weekly / monthly / yearly / never)</em> can be added by appending it after a space.</p><p><strong>Examples:</strong><br><em>/ 1.0 daily</em> -&gt; home page with the highest priority and daily change frequency<br><em>/contact</em> -&gt; contact page with the default priority and no change frequency information</p>\n  </div>\n\";}s:9:\"#attached\";a:0:{}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"route\";i:2;s:5:\"theme\";i:3;s:16:\"user.permissions\";}s:4:\"tags\";a:2:{i:0;s:10:\"block_view\";i:1;s:27:\"config:block.block.gin_help\";}s:7:\"max-age\";i:-1;}}',-1,1777749081.777,1,'block_view config:block.block.gin_help rendered','0'),('entity_view:block:gin_help:[languages:language_interface]=es:[route]=simple_sitemap.entities35786c7117b4e38d0f169239752ce71158266ae2f6e4aa230fbbb87bd699c0e3:[theme]=gin:[user.permissions]=is-admin',_binary 'a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:315:\"<div id=\"block-gin-help\" role=\"complementary\" class=\"block block-help block-help-block\">\n  \n    \n      <p>Simple XML Sitemap settings will be added only to entity forms of entity types enabled here. Settings for specific entity bundles (e.g. <em>page</em>) can be adjusted here or on the bundle pages.</p>\n  </div>\n\";}s:9:\"#attached\";a:0:{}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"route\";i:2;s:5:\"theme\";i:3;s:16:\"user.permissions\";}s:4:\"tags\";a:2:{i:0;s:10:\"block_view\";i:1;s:27:\"config:block.block.gin_help\";}s:7:\"max-age\";i:-1;}}',-1,1777748994.585,1,'block_view config:block.block.gin_help rendered','0'),('entity_view:block:gin_help:[languages:language_interface]=es:[route]=simple_sitemap.entity_bundles305467057a111b5eb8465bf9977e1e230081de0cb1a7c263c8cd17500a2e41fa:[theme]=gin:[user.permissions]=is-admin',_binary 'a:3:{s:7:\"#markup\";s:0:\"\";s:9:\"#attached\";a:0:{}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"route\";i:2;s:5:\"theme\";i:3;s: