--
-- Table structure for table `search_dataset`
--

DROP TABLE IF EXISTS `search_dataset`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `search_dataset` (
  `sid` int unsigned NOT NULL DEFAULT '0' COMMENT 'Search item ID, e.g. node ID for nodes.',
  `langcode` varchar(12) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT '' COMMENT 'The "languages".langcode of the item variant.',
  `type` varchar(64) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL COMMENT 'Type of item, e.g. node.',
  `data` longtext NOT NULL COMMENT 'List of space-separated words from the item.',
  `reindex` int unsigned NOT NULL DEFAULT '0' COMMENT 'Set to force node reindexing.',
  PRIMARY KEY (`sid`,`langcode`,`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Stores items that will be searched.';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `search_dataset`
--

LOCK TABLES `search_dataset` WRITE;
/*!40000 ALTER TABLE `search_dataset` DISABLE KEYS */;
INSERT INTO `search_dataset` VALUES (1,'en','help_search',' viewing drupal announcements what are drupal announcements  a feed of announcements about the drupal project and drupal association programs the purpose of this feed is to provide a channel for outreach directly to drupal site owners this content must be highly relevant to site owners interests serve the strategic goals of the project and or promote the sustainability of the project and the drupal association the module sources its content from a json feed generated from here  the governance policy for the content is documented here  how can i see the announcements in my site  if you have the toolbar module enabled you will see a direct link to them in the toolbar if the toolbar module is not enabled the content can always be accessed in the announcements page who can see the announcements  users with the view official announcements related to drupal permission can view drupal announcements additional resources announcement module overview ',1777497552),(1,'en','node_search',' transforming ideas into reality transforming ideas into reality admin fri 1 may 2026 2146 image we take care of what worries you comprehensive industrial construction and maintenance solutions in punta cana contact us ',1777748775),(1,'es','help_search',' viewing drupal announcements what are drupal announcements  a feed of announcements about the drupal project and drupal association programs the purpose of this feed is to provide a channel for outreach directly to drupal site owners this content must be highly relevant to site owners interests serve the strategic goals of the project and or promote the sustainability of the project and the drupal association the module sources its content from a json feed generated from here  the governance policy for the content is documented here  how can i see the announcements in my site  if you have the toolbar module enabled you will see a direct link to them in the toolbar if the toolbar module is not enabled the content can always be accessed in the anuncios page who can see the announcements  users with the view official announcements related to drupal permission can view drupal announcements recursos adicionales announcement module overview ',1777497552),(1,'es','node_search',' transformando ideas en realidad transformando ideas en realidad admin sab 25 abr 2026 1204 image nos ocupamos de lo que te preocupa soluciones integrales de construccion y mantenimiento industrial en punta cana contacte con nosotros ',1777748775),(2,'en','help_search',' gestionar bloques what are blocks  blocks are boxes of content rendered into an area or region of a web page of your site blocks are placed and configured specifically for each theme what are content blocks  content blocks are blocks whose content you can edit you can define one or more block types  and attach fields to each block type content blocks can be placed just like blocks provided by other modules what is the block description  the block description is an identification name for a block which is shown in the administrative interface it is not displayed on the site what is the block title  the block title is the heading that is optionally shown to site visitors when the block is placed in a region overview for managing blocks the block module allows you to place blocks in regions of your installed themes and configure block settings the block content module allows you to manage block types and content blocks see the related topics listed below for specific tasks additional resources blocks drupal user guide  ',1777497552),(2,'en','node_search',' we build trust day by day we build trust day by day admin fri 1 may 2026 2146 image your peace of mind is our priority experts in industrial projects and maintenance in punta cana contact us ',1777748773),(2,'es','help_search',' gestionar bloques  que son los bloques  los bloques son cajas de contenido representados en un area o region de una pagina web de su sitio los bloques se colocan y configuran especificamente para cada tema what are content blocks  content blocks are blocks whose content you can edit you can define one or more block types  and attach fields to each block type content blocks can be placed just like blocks provided by other modules  que es la descripcion del bloque  la descripcion del bloque es un nombre de identificacion para un bloque que se muestra en la interfaz administrativa no se muestra en el sitio  que es el titulo del bloque  el titulo del bloque es el encabezado que se muestra opcionalmente a los visitantes del sitio cuando el bloque se coloca en una region overview for managing blocks the block module allows you to place blocks in regions of your installed themes and configure block settings the block content module allows you to manage block types and content blocks see the related topics listed below for specific tasks recursos adicionales blocks drupal user guide  ',1777497552),(2,'es','node_search',' construimos confianza dia a dia construimos confianza dia a dia admin sab 25 abr 2026 1216 image  su tranquilidad es nuestra prioridad expertos en proyectos industriales y mantenimiento en punta cana contacte con nosotros ',1777748773),(3,'en','help_search',' colocando un bloque goal place a block into a theme s region steps in the manage administrative menu navigate to structure  block layout click the name of the theme that you want to place the block in optionally click demonstrate block regions to see the regions of the theme find the region where you want the block and click place block in that region a modal dialog will pop up find the block you want to place and click place block  a configure block modal dialog will pop up configure the block and click save block  see configurar un bloque previamente colocado for configuration details  ',1777497552),(3,'en','node_search',' civil engineering civil engineering admin fri 1 may 2026 2154 buildings renovations and finishing lorem ipsum d